const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {test, before, after} = require('node:test');
const {chromium} = require('playwright-core');
// Generated by cargo test from the bundled lists and real Brave engine.
const fixture = JSON.parse(fs.readFileSync(process.env.CUPITOR_BRAVE_FIXTURE ||
  path.join(__dirname, '../../native/adblock/target/brave-fixture.json'), 'utf8'));
const fallback = fs.readFileSync(path.join(__dirname, '../../assets/js/frame_boot.js'), 'utf8');
let browser;
before(async () => { browser = await chromium.launch({
  executablePath:process.env.CUPITOR_CHROME_PATH || '/usr/bin/google-chrome',
  headless:true, args:['--no-sandbox'],
}); });
after(async () => { await browser?.close(); });

async function withPage(run, {embedded = false, csp = false} = {}) {
  const context = await browser.newContext();
  try {
    // One script preserves the native ordering. YouTube scriptlets are inline,
    // independent of prompt transport and unsafe-eval permission.
    await context.addInitScript({content:
      'window.__cupitorBraveBootstrap={ready:true,enabled:true};window.prompt=()=>null;\n' +
      fixture.script + '\n' + fallback});
    const page = await context.newPage();
    await page.route('**/*', route => {
      const url = new URL(route.request().url());
      if (url.pathname.endsWith('/player')) return route.fulfill({contentType:'application/json',
        body:JSON.stringify({adPlacements:[1], adSlots:[2], videoDetails:{videoId:'content'}})});
      if (url.hostname === 'study.example') return route.fulfill({contentType:'text/html',
        body:'<!doctype html><iframe src="https://www.youtube.com/embed/content"></iframe>'});
      const headers = csp ? {'content-security-policy':"script-src 'nonce-fixture'; style-src 'none'"} : {};
      return route.fulfill({contentType:'text/html', headers, body:`<!doctype html>
        <script nonce="fixture">window.ytInitialPlayerResponse={adPlacements:[1],playerAds:[2],adSlots:[3],videoDetails:{videoId:'content'}};
        window.firstRead=[window.ytInitialPlayerResponse.adPlacements,window.ytInitialPlayerResponse.playerAds,window.ytInitialPlayerResponse.adSlots].every(x=>x===undefined);</script>
        <div id="sticker-layer">Ad</div><div id="content">Content</div>`});
    });
    await page.goto(embedded ? 'https://study.example/' : 'https://www.youtube.com/watch?v=content');
    const frame = embedded ? page.frames().find(f => f.url().includes('youtube.com/embed/')) : page.mainFrame();
    assert.ok(frame);
    await run(frame);
  } finally { await context.close(); }
}

for (const embedded of [false, true]) test(`real Brave scriptlets beat the first player read (${embedded ? 'embed' : 'watch'})`, async () => {
  await withPage(async frame => {
    assert.equal(await frame.evaluate(() => window.firstRead), true);
    assert.equal(await frame.evaluate(() => window.ytInitialPlayerResponse.videoDetails.videoId), 'content');
    assert.equal(await frame.evaluate(() => window.__cupitorBraveActive), true);
    assert.equal(await frame.evaluate(() => window._ytAdPruneInstalled), undefined, 'old JSON hooks stand down');
    assert.equal(await frame.evaluate(() => window._ytAdFallbackInstalled), 1, 'Skip fallback remains');
    const result = await frame.evaluate(async () => (await fetch('/youtubei/v1/player')).json());
    assert.equal(result.adPlacements, undefined);
    assert.equal(result.adSlots, undefined);
    assert.equal(result.videoDetails.videoId, 'content');
  }, {embedded});
});

test('YouTube scriptlets and cosmetics work with strict CSP and unavailable prompt transport', async () => {
  await withPage(async frame => {
    assert.equal(await frame.evaluate(() => window.firstRead), true);
    await frame.waitForFunction(() => getComputedStyle(document.querySelector('#sticker-layer')).display === 'none');
    assert.notEqual(await frame.evaluate(() => getComputedStyle(document.querySelector('#content')).display), 'none');
  }, {csp:true});
});
